import json, glob, os, pandas as pd, numpy as np

def clean_and_parse_float(s):
    if isinstance(s, (pd.Series, pd.DataFrame)):
        # Should not happen if we select correctly, but just in case:
        s = s.iloc[:, 0] if isinstance(s, pd.DataFrame) else s
    if pd.isna(s):
        return np.nan
    s = str(s).strip()
    if not s:
        return np.nan
    dot_count = s.count('.')
    comma_count = s.count(',')
    if dot_count > 0 and comma_count > 0:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif comma_count > 0:
        if comma_count > 1:
            s = s.replace(',', '')
        else:
            s = s.replace(',', '.')
    elif dot_count > 1:
        s = s.replace('.', '')
    try:
        return float(s)
    except Exception as e:
        return s

data = json.load(open('/app/dataset/sensors_calibration.json'))
farms = data['enterprise_platform']['deployment_environments']['system_config']['farms']

for fid, fval in sorted(farms.items()):
    fpath = f'/app/dataset/production_{fid}.csv'
    with open(fpath, 'rb') as file:
        head = file.read(4)
        encoding = 'utf-16' if head.startswith(b'\xff\xfe') else 'utf-8'
    with open(fpath, 'r', encoding=encoding) as file:
        lines = [file.readline() for _ in range(5)]
    header_line = lines[3]
    sep = ';' if ';' in header_line else ','

    df = pd.read_csv(fpath, skiprows=3, sep=sep, encoding=encoding)
    col_name = fval['calibration_data']['value_column_name']

    # Check if the exact column exists in df.columns
    if col_name not in df.columns:
        # Maybe there are spaces or it needs stripping?
        # Let's find if a stripped version matches
        matched_col = None
        for col in df.columns:
            if col.strip() == col_name.strip():
                matched_col = col
                break
        if matched_col is not None:
            col_name = matched_col
        else:
            print(f'Error: {fid} col \"{col_name}\" not found in columns: {df.columns.tolist()}')
            continue

    raw_vals = df[col_name]
    if isinstance(raw_vals, pd.DataFrame):
        # If still duplicate, let's take the first one or print warning
        print(f'Warning: {fid} col \"{col_name}\" returned DataFrame')
        raw_vals = raw_vals.iloc[:, 0]

    parsed_vals = raw_vals.apply(clean_and_parse_float)
    non_floats = parsed_vals[parsed_vals.apply(lambda x: isinstance(x, str))]
    if len(non_floats) > 0:
        print(f'{fid}: Found non-float values in \"{col_name}\" ({type(raw_vals)}):', non_floats.unique())
    else:
        # Print some stats of floats
        floats = parsed_vals.dropna()
        print(f'{fid}: Min={floats.min()}, Max={floats.max()}, Nulls={parsed_vals.isna().sum()}')
"

